```matlab
arrival = [0 4 5 9 11 15];
service = [2 3 1 4 2 3];
n = numel(arrival);
begin = zeros(1,n); departure = zeros(1,n);
wait = zeros(1,n); systemTime = zeros(1,n); idle = zeros(1,n);
previousEnd = 0;
for i = 1:n
    begin(i) = max(arrival(i),previousEnd);
    wait(i) = begin(i)-arrival(i);
    departure(i) = begin(i)+service(i);
    systemTime(i) = departure(i)-arrival(i);
    idle(i) = max(0,arrival(i)-previousEnd);
    previousEnd = departure(i);
end
fprintf('i arrival service begin wait end system idle\n');
fprintf('%d %d %d %d %d %d %d %d\n',[(1:n); arrival; service; begin; wait; departure; systemTime; idle]);
fprintf('totals: service=%d wait=%d system=%d idle=%d\n',sum(service),sum(wait),sum(systemTime),sum(idle));
fprintf('mean wait=%.6f mean system=%.6f utilization=%.6f\n',mean(wait),mean(systemTime),sum(service)/departure(end));
```

